import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1788625494000}`),a={name:`guide/quick-start.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h1><p>本页适合第一次使用草丛 Mail 的用户。网页应用统一位于 <code>/app</code>，旧版地址会自动跳转。</p><h2 id="_1-注册或登录" tabindex="-1">1. 注册或登录 <a class="header-anchor" href="#_1-注册或登录" aria-label="Permalink to “1. 注册或登录”">​</a></h2><p>打开 <a href="https://to9.us/app/login" target="_blank" rel="noreferrer">https://to9.us/app/login</a>。页面可能提供以下方式，实际可用项由管理员配置：</p><ul><li>本地账号：输入用户名和密码。</li><li>NodeLoc OAuth：跳转到 NodeLoc 授权后返回草丛 Mail。</li><li>邮箱注册：在 <a href="https://to9.us/app/register" target="_blank" rel="noreferrer">https://to9.us/app/register</a> 填写用户名和密码。未强制邮件认证时找回邮箱可以留空，之后再到账号设置中绑定；管理员启用邮件认证后，找回邮箱为必填，并需输入收到的验证码后才会创建账号。注册入口是否开放以页面显示为准。</li></ul><p>如果忘记本地密码，可在 <a href="https://to9.us/app/forgot-password" target="_blank" rel="noreferrer">https://to9.us/app/forgot-password</a> 使用已验证的绑定邮箱接收重置码。未绑定邮箱的账号需要联系管理员重置。</p><h2 id="_2-完成首次引导" tabindex="-1">2. 完成首次引导 <a class="header-anchor" href="#_2-完成首次引导" aria-label="Permalink to “2. 完成首次引导”">​</a></h2><p>真正的新账号登录后会进入首次引导页。已经创建过邮箱或已经完成引导的账号再次登录时会直接进入邮箱；管理员账号直接进入后台，不需要重复绑定或创建个人邮箱。个人邮箱的数量、存储和每日发信量由系统配额等级、个人套餐及管理员覆盖值共同决定；企业邮箱的数量、存储和全组织共享每日发信量由组织订阅管理。</p><h2 id="_3-创建邮箱" tabindex="-1">3. 创建邮箱 <a class="header-anchor" href="#_3-创建邮箱" aria-label="Permalink to “3. 创建邮箱”">​</a></h2><p>进入“管理 → 邮箱管理”，填写邮箱前缀并选择可注册域名。系统会实时检查地址是否可用。以下类型的前缀通常保留给平台管理：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>admin</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>postmaster</span></span>
<span class="line"><span>security</span></span>
<span class="line"><span>abuse</span></span></code></pre></div><p>创建后可设置显示名称、排序、外部转发、自动回复和应用专用密码。邮箱级转发可以填写有效外部邮箱；收信规则里的转发只允许本人已验证的找回邮箱。两者都会使用正常出站路由并计入相应的个人或组织每日发信额度；个人邮箱超出免费额度时可能消耗能量。设置后应发送专用测试邮件。平台也可能关闭某个域名的公开注册，或设置最低用户等级。</p><h2 id="_4-收信与发信" tabindex="-1">4. 收信与发信 <a class="header-anchor" href="#_4-收信与发信" aria-label="Permalink to “4. 收信与发信”">​</a></h2><p>点击左上角邮箱选择器，在单个邮箱和“全部邮箱”之间切换。点击“写邮件”选择发件地址，填写收件人、主题、正文和附件。</p><p>若管理员对公共域名启用了发信审批策略，页面会提示当前不能发信；此时可在写信页提交发信权限申请，管理员批准后才能使用相应域名发信。是否需要审批以页面当前状态为准。</p><h2 id="_5-完成安全设置" tabindex="-1">5. 完成安全设置 <a class="header-anchor" href="#_5-完成安全设置" aria-label="Permalink to “5. 完成安全设置”">​</a></h2><p>建议首次登录后立即完成：</p><ol><li>本地账号绑定并验证找回邮箱；第三方登录账号通过原登录平台维护恢复方式。</li><li>开启 TOTP 两步验证，并在启用时安全备份 TOTP 密钥；当前不提供一次性恢复码。</li><li>检查登录历史和活动会话。</li><li>需要第三方客户端时，为每个邮箱单独创建应用专用密码，不要使用网页登录密码。</li></ol><p>具体步骤见<a href="/nodemail-docs/guide/account-security">账号与安全</a>。</p><p>若使用 NodeLoc，请同时阅读 <a href="/nodemail-docs/guide/nodeloc-identity">NodeLoc 身份、等级与本站配额</a>，不要把 NodeLoc 的 <code>TL</code> 会员等级与本站的 <code>L</code> 配额档位混为一谈。</p><h2 id="_6-认识主要页面" tabindex="-1">6. 认识主要页面 <a class="header-anchor" href="#_6-认识主要页面" aria-label="Permalink to “6. 认识主要页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用途</th></tr></thead><tbody><tr><td>邮件</td><td>收件箱、文件夹、搜索、会话阅读和写信</td></tr><tr><td>数据面板</td><td>邮件数量、趋势与常用联系人</td></tr><tr><td>邮箱管理</td><td>地址、显示名、排序、自动回复和客户端密码</td></tr><tr><td>联系人</td><td>通讯录与自动发现的往来地址</td></tr><tr><td>规则</td><td>自动处理来信</td></tr><tr><td>被拦截邮件</td><td>安全预览、放行或永久删除高风险隔离邮件</td></tr><tr><td>共享</td><td>直接授权其他用户只读查看指定范围</td></tr><tr><td>清理中心</td><td>对本人个人邮箱执行延迟删除、取消清理、永久保留与彻底清空；企业邮箱不在此范围</td></tr><tr><td>企业邮局</td><td>组织、域名、成员、企业邮箱和品牌</td></tr><tr><td>我的套餐</td><td>套餐、订阅、兑换码与配额</td></tr><tr><td>订单与账单</td><td>钱包、充值、订单和交易记录</td></tr><tr><td>通知中心</td><td>系统公告和个人事件通知</td></tr><tr><td>开发者</td><td>API 密钥与接口说明</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/nodemail-docs/guide/mail">收发与整理邮件</a></li><li><a href="/nodemail-docs/guide/mailboxes">邮箱管理</a></li><li><a href="/nodemail-docs/guide/organizations">企业邮局</a></li><li><a href="/nodemail-docs/guide/plans-billing">套餐、钱包与订单</a></li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};